/**
 * The typed `window.cc` client (ADR 0008 decision 1). `UiMethods` is generated by
 * `pnpm cc:gen` from the methods marked `ui` in @cc/schemas, so a screen's params and results
 * are the schemas' own types, never hand-copied ones. The methods, their params and results
 * are stable within an extension API version: `pnpm cc:gen --check` fails on an incompatible
 * change until the version is bumped (`packages/ui-sdk/contract/v<N>.json`).
 */
import type { CcBridge, ShellInfo } from './bridge.js';
import type { UiMethods } from './generated/methods.js';

export type { UiMethods };

/** A local API method the app window may call. */
export type UiMethod = keyof UiMethods;

/** What the window sends to `method`. */
export type Params<M extends UiMethod> = UiMethods[M]['params'];

/** What `method` answers. */
export type Result<M extends UiMethod> = UiMethods[M]['result'];

/** The extension API version this entry point speaks (`@cc/ui-sdk/v1`). */
export const API_VERSION = 1;
export type ApiVersion = typeof API_VERSION;

export interface Client {
  /** One local API call as the user. Rejects with a `CcError`. */
  call<M extends UiMethod>(method: M, params: Params<M>): Promise<Result<M>>;
}

/** The typed client over `window.cc.invoke` (or a test's fake of it). */
export function createClient(bridge: Pick<CcBridge, 'invoke'>): Client {
  return {
    call: <M extends UiMethod>(method: M, params: Params<M>) =>
      bridge.invoke(method, params) as Promise<Result<M>>,
  };
}

/**
 * Why this UI cannot run on the shell it is in, or `undefined` when it can: the shell speaks
 * another `window.cc` API version than the one the UI was built for (08 §4.3). The UI shows
 * the reason instead of calling methods whose shapes it does not know.
 */
export function apiVersionProblem(
  shell: Pick<ShellInfo, 'apiVersion'>,
  expected: number = API_VERSION,
): string | undefined {
  if (shell.apiVersion === expected) return undefined;
  return `This app's UI was built for window.cc API ${String(expected)}, but the app shell speaks API ${String(shell.apiVersion)}. Rebuild the app from your engine (pnpm cc:upgrade, then pnpm build).`;
}
